class SshConnection:
    __MISSING_IMPLEMENTATION_ERROR_MSG = "{} class has missing implementation of {} method"

    def __init__(self):
        self.tcpdump_remote_path = ''
        self._tcpdump_pid = None

    def connect_to(self):
        """
        Opens ssh connection to SMOD with the credentials from init file
        """
        self._connect_to()

    def close_connection(self):
        """
        Closes previously opened ssh connection to SMOD
        """
        self._close_connection()

    def send_command(self, command, timeout=None):
        """
        Sends a command to the remote using the instance designated by the
        connection parameter, waits for the execution to finish, and returns
        the outputs' contents (both stdout and stdin).

        :param command: The linux command.
        :type command: str
        :param timeout: (optional) Timeout for keyword execution, None by
            default. Accepts a timeout string in Robot Framework format.
            If None, waits for the command to end indefinitely.
        :type timeout: str or int
        """
        self._send_command(command=command, timeout=timeout)

    def execute(self, command, timeout=None):
        """
        Sends a command to the remote using the instance designated by the
        connection parameter, waits for the execution to finish, and returns
        the outputs' contents (both stdout and stdin).

        :param command: The linux command.
        :type command: str
        :param timeout: (optional) Timeout for keyword execution, None by
            default. Accepts a timeout string in Robot Framework format.
            If None, waits for the command to end indefinitely.
        :type timeout: str or int
        """
        return self._execute(command=command, timeout=timeout)

    def start_tcpdump_and_get_filepath(self, file_path='/tmp/log.pcap'):
        """
        Starts collection of PCAP file
        :param file_path: desired destination of PCAP file, default file_path: /tmp/log.pcap
        :type file_path: str

        :returns path where PCAP was created
        :rtype: str
        """
        self._tcpdump_pid = self._start_tcpdump(file_path=file_path)

        self.tcpdump_remote_path = file_path
        return self.tcpdump_remote_path

    def stop_tcpdump_collection_and_download_logs(self, local_path, remote_path):
        """
        Stops collection of PCAP file and downloads the file from system module
        :param local_path: local path to which pcap file should be downloaded
        :type local_path: str
        :param remote_path: location of pcap file on system module
        :type remote_path: str
        """
        self._stop_tcpdump()
        self._download_file(local_path=local_path, remote_path=remote_path)
        self._clean_up_environment_after_tcpdump_collection(remote_path=remote_path)

    def stop_tcpdump(self):
        """
        Stops collection of PCAP file
        """
        self._stop_tcpdump()

    def download_file(self, remote_path, local_path):
        """
        Downloads file from SMOD with given remote_path
        and saves it into local_path
        """
        self._download_file(local_path=local_path, remote_path=remote_path)

    def _connect_to(self):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                           "_connect_to"))

    def _close_connection(self):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                           "_close_connection"))

    def _send_command(self, command, timeout=None):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                           "_send_command"))

    def _execute(self, command, timeout=None):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                           "_execute"))

    def _start_tcpdump(self, file_path):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                           "_start_tcpdump"))

    def _stop_tcpdump(self):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                           "_stop_tcpdump"))

    def _download_file(self, local_path, remote_path):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                           "_download_file"))

    def _clean_up_environment_after_tcpdump_collection(self, remote_path):
        raise NotImplementedError(
            self.__MISSING_IMPLEMENTATION_ERROR_MSG.format(self.__class__.__name__,
                                                           "_clean_up_environment_after_tcpdump_collection"))
